        self.val = val
        self.left = left
        self.right = right

class Solution:
    def singlevalued(self, root):
        def is_single_valued(node):
            if not node:
                return True, 0
            left_is_single, left_count = is_single_valued(node.left)
            right_is_single, right_count = is_single_valued(node.right)
